select id, plan, tier_limits, zip_with(tier_prices, discounts, (p, d) -> round(p * (1 - d), 2)) as net_prices, transform(tier_prices, (p, i) -> round(p * tier_limits[i], 2)) as tier_revenue_caps, aggregate(tier_prices, cast(0 as double), (acc, p) -> acc + p, acc -> round(acc / size(tier_prices), 2)) as avg_tier_price, array_min(tier_prices) as lowest_price, slice(tier_limits, 1, 2) as first_two_limits from price_tiers
